void main() {
  test('lrc.red documented search shape parses into ranked candidates', () {
    final hits = LrcRedService.parseSearch(json_decoded(kRedSearch));
    expect(hits, hasLength(3));
    final first = hits.first;
    expect(first.isrc, 'GBAYE9200070');
    expect(first.title, 'Creep');
    expect(first.artist, 'Radiohead');
    // Documented duration is seconds (238.64), stored as ms.
    expect(first.duration, const Duration(milliseconds: 238640));
    expect(
      LrcRedMatcher.accept(first,
          title: 'Creep', artist: 'Radiohead', album: 'Pablo Honey',
          duration: const Duration(seconds: 238)),
      isTrue,
    );
  });

  test('real lrc.red TTML parses to syllable-level karaoke timing', () {
    final track = parseTtml(kCreepTtml,
        duration: const Duration(seconds: 238), sourceUrl: 'https://lrc.red/s/GBAYE9200070');
    expect(track, isNotNull);
    expect(track!.lines, hasLength(4));
    expect(track.hasRealWordSync, isTrue);
    // "be"+"fore" fragments -> syllable, never a downgrade to line timing.
    expect(track.type, LyricsSyncType.syllable);
    final fragments =
        track.lines.expand((l) => l.syllables).where((s) => s.isPartOfWord);
    expect(fragments, isNotEmpty);
    // Real timestamps survive: first word starts at 19.764s per the file.
    expect(track.lines.first.start, const Duration(milliseconds: 19764));
  });

  test('real LRCLIB record prefers its word-synced lyricsfile (karaoke)', () {
    final record = json_decoded(kLrclibRecord);
    final track = trackFromRecord(record,
        duration: const Duration(seconds: 239),
        source: LyricsSource.lrclib,
        matchDelta: const Duration(milliseconds: 360));
    expect(track, isNotNull);
    // The record ships a word-timed lyricsfile: it wins over the line LRC.
    expect(track!.type, LyricsSyncType.syllable);
    expect(track.hasRealWordSync, isTrue);
    expect(track.lines, hasLength(37));
    expect(track.matchedTitle, 'Creep');
    // Real word timestamps survive: first word at 19.98s per the file.
    expect(track.lines.first.syllables.first.start, const Duration(milliseconds: 19980));
  });

  test('the same record without a lyricsfile is line-synced, never karaoke', () {
    final record = json_decoded(kLrclibRecord) as Map<String, dynamic>;
    record.remove('lyricsfile');
    final track = trackFromRecord(record,
        duration: const Duration(seconds: 239),
        source: LyricsSource.lrclib,
        matchDelta: const Duration(milliseconds: 360));
    expect(track, isNotNull);
    expect(track!.type, LyricsSyncType.line);
    expect(track.hasRealWordSync, isFalse); // estimated only — no fake karaoke
    expect(track.lines, hasLength(6)); // trimmed syncedLyrics in the fixture
  });
}

dynamic json_decoded(String s) => jsonDecode(s);
